#include <string>

using namespace std;

class Solution {
public:
    bool isValid(string s) {
        string stack;
        for (char c : s) {
            stack.push_back(c);
            if (stack.size() >= 3 && stack.substr(stack.size() - 3) == "abc") {
                stack.erase(stack.end() - 3, stack.end());
            }
        }
        return stack.empty();
    }
};
